package com.movieworth.api.boxoffice;import org.springframework.data.jpa.repository.JpaRepository;import org.springframework.data.jpa.repository.Query;import java.time.LocalDate;import java.util.*;
public interface CollectionRepository extends JpaRepository<CollectionSnapshot,Long>{List<CollectionSnapshot> findByMovieIdOrderByCollectionDateDesc(Long movieId);List<CollectionSnapshot> findByCollectionDateOrderByWorldwideGrossCrDesc(LocalDate date);Optional<CollectionSnapshot> findByMovieIdAndCollectionDateAndSource(Long movieId,LocalDate date,String source);@Query("select c from CollectionSnapshot c where c.collectionDate=(select max(x.collectionDate) from CollectionSnapshot x) order by c.worldwideGrossCr desc")List<CollectionSnapshot> latestTop();}